pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {LiquidityPool} from "../src/LiquidityPool.sol";

contract InvMutTest is Test {
    LiquidityPool c;
    function setUp() public { c = new LiquidityPool(0, bytes16(0), address(this), address(this), address(this)); }
    function testRegression_property() public {
        address alice = address(0x1234);
        c.rely(alice);
        vm.prank(alice);
        c.deny(alice);
        uint256 wardsAliceRef = c.wards(alice);
        assertTrue(wardsAliceRef == 0, "wards[alice] should be 0 after deny");
    }
}
